local esp = {}
local fovCircle
local function dropESP(k) local e = esp[k] if e then for _, d in pairs(e) do pcall(function() d:Remove() end) end esp[k] = nil end end
onClean(function() for k in pairs(esp) do dropESP(k) end if fovCircle then pcall(function() fovCircle:Remove() end) end end)
if Drawing then
    local function text() local t = Drawing.new("Text") t.Center = true t.Outline = true t.Size = 13 t.Visible = false return t end
    local function draw(seen, key, head, root, col, top, bottom, from)
        local cam = G.cam
        local _, vis = cam:WorldToViewportPoint(root.Position)
        if not vis then return end
        seen[key] = true
        local e = esp[key]
        if not e then
            local b = Drawing.new("Square") b.Thickness = 1 b.Filled = false b.Visible = false
            local l = Drawing.new("Line") l.Thickness = 1 l.Transparency = 0.9 l.Visible = false
            e = { box = b, top = text(), bot = text(), line = l }
            esp[key] = e
        end
        local a = cam:WorldToViewportPoint(head.Position + Vector3.new(0, 1, 0))
        local z = cam:WorldToViewportPoint(root.Position - Vector3.new(0, 3, 0))
        local hgt = math.abs(a.Y - z.Y)
        e.box.Color, e.box.Position, e.box.Size, e.box.Visible = col, Vector2.new(a.X - hgt / 4, a.Y), Vector2.new(hgt / 2, hgt), true
        e.top.Visible = top ~= nil
        if top then e.top.Color, e.top.Text, e.top.Position = col, top, Vector2.new(a.X, a.Y - 16) end
        e.bot.Visible = bottom ~= nil
        if bottom then e.bot.Color, e.bot.Text, e.bot.Position = col, bottom, Vector2.new(z.X, z.Y + 2) end
        e.line.Visible = from ~= nil
        if from then e.line.Color, e.line.From, e.line.To = col, from, Vector2.new(z.X, z.Y) end
    end
    fovCircle = Drawing.new("Circle")
    fovCircle.Thickness = 1.5 fovCircle.NumSides = 64 fovCircle.Filled = false fovCircle.Transparency = 0.8 fovCircle.Color = Color3.fromRGB(245, 197, 66) fovCircle.Visible = false
    local C_BRUTE, C_HORDE, C_DUMMY = Color3.fromRGB(255, 120, 60), Color3.fromRGB(150, 255, 120), Color3.fromRGB(235, 228, 210)
    local C_ENEMY, C_FRIEND, C_SAFE = Color3.fromRGB(255, 80, 80), Color3.fromRGB(110, 200, 255), Color3.fromRGB(160, 160, 160)
    track(RunService.RenderStepped:Connect(function()
        local cam = G.cam
        local fov = val("c_fov", 60)
        if RUNNING and on("c_silent") and on("c_circle") and fov < 170 then
            fovCircle.Position = G.aimPoint()
            fovCircle.Radius = math.tan(math.rad(fov / 2)) / math.tan(math.rad(cam.FieldOfView / 2)) * (cam.ViewportSize.Y / 2)
            fovCircle.Visible = true
        else
            fovCircle.Visible = false
        end
        local seen = {}
        local camPos = cam.CFrame.Position
        local pick = val("pv_from", "Bottom")
        local vs = cam.ViewportSize
        local from = pick == "Mouse" and UIS:GetMouseLocation() or pick == "Center" and vs / 2 or Vector2.new(vs.X / 2, vs.Y - 2)
        if RUNNING and on("v_esp") and G.Dummies then
            local maxD = val("v_max", 400)
            for _, f in ipairs(G.Dummies:GetChildren()) do
                local horde = f.Name == "Horde"
                for _, m in ipairs(f:GetChildren()) do
                    local c = partsOf(m)
                    local root = c and (m:FindFirstChild("UpperTorso") or m:FindFirstChild("HumanoidRootPart"))
                    if root and c.hum.Health > 0 then
                        local dist = (camPos - root.Position).Magnitude
                        if dist <= maxD then
                            local col = c.brute and C_BRUTE or horde and C_HORDE or C_DUMMY
                            local tag = on("v_name") and (c.brute and "Brute" or horde and "Zombie" or (m:GetAttribute("Fighter") and "Armed" or "Dummy")) or nil
                            local parts = {}
                            if on("v_dist") then parts[#parts + 1] = math.floor(dist) .. "m" end
                            if on("v_hp") then parts[#parts + 1] = math.floor(c.hum.Health) .. "hp" end
                            draw(seen, m, c.head, root, col, tag, #parts > 0 and table.concat(parts, " · ") or nil, on("v_tracer") and from or nil)
                        end
                    end
                end
            end
        end
        if RUNNING and on("pv_esp") then
            local maxD = val("pv_max", 1000)
            local hideNames = on("st_others")
            for _, p in ipairs(Players:GetPlayers()) do
                if p ~= lp then
                    local ch = p.Character
                    local h = ch and ch:FindFirstChildOfClass("Humanoid")
                    local head = ch and ch:FindFirstChild("Head")
                    local root = ch and ch:FindFirstChild("HumanoidRootPart")
                    if h and head and root and h.Health > 0 then
                        local dist = (camPos - root.Position).Magnitude
                        if dist <= maxD then
                            local safe = G.safe(root.Position)
                            local col = G.friend(p) and C_FRIEND or safe and C_SAFE or C_ENEMY
                            local parts = {}
                            if on("pv_dist") then parts[#parts + 1] = math.floor(dist) .. "m" end
                            if on("pv_hp") then parts[#parts + 1] = math.floor(h.Health) .. "hp" end
                            if on("pv_tool") then local t = ch:FindFirstChildOfClass("Tool") if t then parts[#parts + 1] = t.Name end end
                            draw(seen, p, head, root, col, on("pv_name") and (hideNames and "Player" or p.DisplayName) or nil, #parts > 0 and table.concat(parts, " · ") or nil, on("pv_tracer") and from or nil)
                        end
                    end
                end
            end
        end
        for k in pairs(esp) do if not seen[k] then dropESP(k) end end
    end))
end
local V = { fps = false, fpsAt = 0, recoil = G.WC and G.WC.Kick, noRecoil = false, speedOn = false, saved = nil }
G.GS = gcall(require, G.Shared:WaitForChild("Settings"))
local LOWFX = { Blood = "Off", Gore = "Off", GorePack = "Off", Screams = "Off", Graphics = "Low" }
local function setQuality(low)
    pcall(function() settings().Rendering.QualityLevel = low and Enum.QualityLevel.Level01 or Enum.QualityLevel.Automatic end)
    if not (G.GS and G.GS.Set and G.GS.Get) then return end
    gcall(function()
        if low then
            V.saved = {}
            for k, v in pairs(LOWFX) do V.saved[k] = G.GS.Get(k) G.GS.Set(k, v) end
        elseif V.saved then
            for k, v in pairs(V.saved) do G.GS.Set(k, v) end
            V.saved = nil
        end
    end)
end
onClean(function()
    if V.fps then setQuality(false) end
    if V.noRecoil and G.WC then G.WC.Kick = V.recoil end
end)
track(RunService.Heartbeat:Connect(function()
    local f = on("v_fps")
    if f ~= V.fps then V.fps = f setQuality(f) end
    if f and os.clock() - V.fpsAt > 3 then
        V.fpsAt = os.clock()
        for _, n in ipairs({ "Gibs" }) do local x = Workspace:FindFirstChild(n) if x then pcall(function() x:ClearAllChildren() end) end end
    end
    local sa = on("c_silent")
    if sa ~= (SA.saved ~= nil) then setSpread(sa) end
    local r = on("c_norecoil")
    if r ~= V.noRecoil and G.WC and V.recoil then V.noRecoil = r G.WC.Kick = r and function() end or V.recoil end
    local h = hum()
    if h then
        if on("p_speed") then
            local s = math.clamp(val("p_speedv", 28), 16, 50)
            if h.WalkSpeed < s then h.WalkSpeed = s end
            V.speedOn = true
        elseif V.speedOn then
            V.speedOn = false
            if h.WalkSpeed > 16 then h.WalkSpeed = 16 end
        end
    end
end))
local fly = { on = false, starting = false }
local function stopFly()
    fly.on = false
    if fly.lv then pcall(function() fly.lv:Destroy() end) fly.lv = nil end
    if fly.att then pcall(function() fly.att:Destroy() end) fly.att = nil end
    local h = hum() if h then pcall(function() h.PlatformStand = false h:ChangeState(Enum.HumanoidStateType.Freefall) end) end
    local t, r = G.held(), hrp()
    if t and r and t:GetAttribute("WeaponId") == "WitchBroom" then pcall(function() G.WA:FireServer("Broom", t, r.Position, false) end) end
end
onClean(stopFly)
local function startFly()
    fly.starting = true
    local t, r, c = G.held(), hrp(), char()
    if t and r and c and t:GetAttribute("WeaponId") == "WitchBroom" then
        G.WA:FireServer("Broom", t, r.Position, true)
        local t0 = os.clock()
        while RUNNING and not c:GetAttribute("BroomFlying") and os.clock() - t0 < 1.5 do task.wait() end
        local root = hrp()
        if c:GetAttribute("BroomFlying") and on("p_fly") and root then
            fly.att = Instance.new("Attachment")
            fly.att.Parent = root
            fly.lv = Instance.new("LinearVelocity")
            fly.lv.Attachment0 = fly.att fly.lv.RelativeTo = Enum.ActuatorRelativeTo.World fly.lv.MaxForce = math.huge fly.lv.VectorVelocity = Vector3.zero
            fly.lv.Parent = root
            local h = hum() if h then h.PlatformStand = true end
            fly.on = true
        else
            notify(L["Broom did not take off"])
            pcall(function() Toggles.p_fly:SetValue(false) end)
        end
    else
        notify(L["Hold the Witch Broom first"])
        pcall(function() Toggles.p_fly:SetValue(false) end)
    end
    fly.starting = false
end
track(RunService.Heartbeat:Connect(function()
    local want = on("p_fly")
    if want and not fly.on and not fly.starting then task.spawn(startFly)
    elseif not want and fly.on then stopFly()
    elseif fly.on then
        if not (fly.lv and fly.lv.Parent and fly.lv.Parent == hrp()) then stopFly() pcall(function() Toggles.p_fly:SetValue(false) end) return end
        local cf = G.cam.CFrame
        local dir = Vector3.zero
        if not UIS:GetFocusedTextBox() then
            if UIS:IsKeyDown(Enum.KeyCode.W) then dir += cf.LookVector end
            if UIS:IsKeyDown(Enum.KeyCode.S) then dir -= cf.LookVector end
            if UIS:IsKeyDown(Enum.KeyCode.A) then dir -= cf.RightVector end
            if UIS:IsKeyDown(Enum.KeyCode.D) then dir += cf.RightVector end
            if UIS:IsKeyDown(Enum.KeyCode.Space) then dir += Vector3.yAxis end
            if UIS:IsKeyDown(Enum.KeyCode.LeftControl) then dir -= Vector3.yAxis end
        end
        fly.lv.VectorVelocity = dir.Magnitude > 0.1 and dir.Unit * math.clamp(val("p_flyv", 55), 20, 70) or Vector3.zero
    end
end))
