local function farmTick()
    local horde, aura = on("f_horde"), on("f_aura")
    if on("f_stop") and (horde or aura) then
        local kind = val("f_stopkind", "Level")
        local goal = tonumber(val("f_stopval", "0")) or 0
        if goal > 0 and ((kind == "Kills" and G.kills()) or G.level()) >= goal then
            pcall(function() Toggles.f_horde:SetValue(false) end)
            pcall(function() Toggles.f_aura:SetValue(false) end)
            notify(L["Reached "] .. kind .. " " .. goal .. L[" - farm stopped"])
            return
        end
    end
    if not (horde or aura) then S.task = L["Idle"] return end
    if G.busy() then S.task = L["Getting up"] return end
    if horde then
        local w = farmWeapon()
        if not G.equip(w) then S.task = L["Getting "] .. w return end
        if not hordeBusy() and os.clock() - S.lastPress > 3 and os.clock() - S.hordeEndAt > 1 then
            S.task = L["Starting wave"]
            pressHorde()
            return
        end
    end
    local tool = G.held()
    local cfg = G.cfgOf(tool)
    local kind = G.kind(cfg)
    if not kind then S.task = L["Hold a gun or staff"] return end
    S.weapon = tool.Name
    if os.clock() < F.reloadUntil then S.task = L["Reloading"] return end
    if os.clock() - F.lastShot < gap(cfg) then return end
    if kind == "gun" and ammo(tool, cfg) <= 0 then reload(tool, cfg) S.task = L["Reloading"] return end
    if os.clock() < (S.idleUntil or 0) then return end
    local targets = scan(cfg.Range or 300, kind == "gun", aura or val("f_targets", "Zombies only") == "Zombies + Dummies", nil, nil, aura and on("f_players"))
    if #targets == 0 then
        S.idleUntil = os.clock() + 0.3
        S.task = horde and (hordeBusy() and L["Clearing wave"] or L["Waiting for wave"]) or L["No targets in range"]
        return
    end
    if kind == "strike" then strike(tool, cfg, targets) else shoot(tool, cfg, targets) end
    S.task = horde and L["Farming horde"] or L["Kill aura"]
end
task.spawn(function()
    while RUNNING do
        local ok, err = pcall(farmTick)
        if not ok then LOG("farm", err) end
        task.wait(0.05)
    end
end)
task.spawn(function()
    while RUNNING do
        if getgenv().Library ~= Library then getgenv().Library = Library end
        pcall(function()
            local m = os.clock() - S.msgAt < 8 and S.msg or ""
            setText(UI.task, "<b>" .. S.task .. "</b>" .. (m ~= "" and ('\n<font color="#9a9a9a">' .. m .. "</font>") or ""))
            setText(UI.stats, string.format(L["Kills  <b>%s</b>\nLevel  <b>%d</b>  ·  %s"], fmt(G.kills()), G.level(), tostring(lp:GetAttribute("Rank") or "-")))
            if on("f_horde") or on("f_aura") then
                if not S.farmStart then S.farmStart, S.farmKills0, S.hordes = os.clock(), G.kills(), 0 end
                local t = os.clock() - S.farmStart
                local got = G.kills() - S.farmKills0
                setText(UI.sess, string.format(L["Time  %s\nGained  +%s  (%s/hr)\nWaves  %d  ·  %s"], clock(t), fmt(got), fmt(got / math.max(t, 1) * 3600), S.hordes, S.weapon))
            else
                S.farmStart = nil
                setText(UI.sess, '<font color="#9a9a9a">Start a farm to see stats.</font>')
            end
        end)
        task.wait(1)
    end
end)
section(L["Streamer"], function()
    local Tab = Window:AddTab(L["Streamer"], "eye")
    local ST = { HideMe = false, FakeName = "Player", HideOthers = false, HideAvatars = false, HidePlayerList = false, HideChat = false }
    ST.conns, ST.objConns, ST.orig, ST.written, ST.alias = {}, setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
    ST.aliasN, ST.rev = 0, {}
    local rules, ids = {}, {}
    local function aliasFor(plr)
        if plr == lp then return (ST.FakeName ~= "" and ST.FakeName) or "Player" end
        if not ST.alias[plr] then ST.aliasN = ST.aliasN + 1 ST.alias[plr] = "Player " .. ST.aliasN end
        return ST.alias[plr]
    end
    local function active() return ST.HideMe or ST.HideOthers or ST.HideAvatars end
    local function esc(s) return (s:gsub("[%^%$%(%)%%%.%[%]%*%+%-%?]", "%%%0")) end
    local ZW = utf8.char(0x200B)
    local function unfix(t)
        if not t:find(ZW, 1, true) then return t end
        local keys = {} for k in pairs(ST.rev) do keys[#keys + 1] = k end
        table.sort(keys, function(a, b) return #a > #b end)
        for _, k in ipairs(keys) do if t:find(k, 1, true) then t = t:gsub(esc(k), (ST.rev[k]:gsub("%%", "%%%%"))) end end
        return (t:gsub(ZW, ""))
    end
    local function rebuild()
        rules, ids = {}, {}
        local seen = {}
        for _, plr in ipairs(Players:GetPlayers()) do
            local mine = plr == lp
            if (mine and ST.HideMe) or (not mine and ST.HideOthers) then
                local a = aliasFor(plr)
                for i, n in ipairs({ plr.DisplayName, plr.Name }) do
                    if type(n) == "string" and #n >= 3 and not seen[n] then
                        seen[n] = true
                        local rep = a .. ZW .. (i == 2 and ZW or "")
                        rules[#rules + 1] = { pat = "%f[%w_]" .. esc(n) .. "%f[^%w_]", plain = n, rep = rep }
                        ST.rev[rep] = n
                    end
                end
            end
            if ST.HideAvatars and (mine or ST.HideOthers) then ids[#ids + 1] = tostring(plr.UserId) end
        end
        table.sort(rules, function(a, b) return #a.plain > #b.plain end)
    end
    local function fixText(t) local o = t for _, r in ipairs(rules) do if o:find(r.plain, 1, true) then o = o:gsub(r.pat, (r.rep:gsub("%%", "%%%%"))) end end return o end
    local function fixImg(img) for _, id in ipairs(ids) do if img:find("=" .. id, 1, true) then return "" end end return img end
    local function propOf(d) if d:IsA("TextLabel") or d:IsA("TextButton") then return "Text" elseif d:IsA("ImageLabel") or d:IsA("ImageButton") then return "Image" end end
    local function process(d)
        local p = propOf(d) if not p then return end
        local cur = d[p]
        if ST.written[d] ~= nil and cur == ST.written[d] then return end
        local fixed = p == "Text" and fixText(cur) or fixImg(cur)
        if fixed ~= cur then ST.orig[d], ST.written[d] = cur, fixed d[p] = fixed else ST.orig[d], ST.written[d] = nil, nil end
    end
    local function watch(d) if ST.objConns[d] then return end local p = propOf(d) if not p then return end ST.objConns[d] = d:GetPropertyChangedSignal(p):Connect(function() if active() then pcall(process, d) end end) pcall(process, d) end
    local function walk(inst, d) if d > 60 then return end local ok, k = pcall(inst.GetChildren, inst) if not ok then return end for _, c in ipairs(k) do pcall(watch, c) walk(c, d + 1) end end
    local function setHum(plr) local h = plr.Character and plr.Character:FindFirstChildOfClass("Humanoid") if h then local hide = (plr == lp and ST.HideMe) or (plr ~= lp and ST.HideOthers) pcall(function() h.DisplayName = hide and aliasFor(plr) or plr.DisplayName end) end end
    local function startWatch()
        if ST.watching then return end
        ST.watching = true
        local roots = { lp:WaitForChild("PlayerGui") }
        pcall(function() roots[#roots + 1] = game:GetService("CoreGui") end)
        pcall(function() local h = gethui and gethui() if typeof(h) == "Instance" then roots[#roots + 1] = h end end)
        pcall(function() roots[#roots + 1] = Workspace end)
        for i, rt in ipairs(roots) do walk(rt, 0) ST.conns["a" .. i] = rt.DescendantAdded:Connect(function(d) if propOf(d) then task.defer(function() if active() and d.Parent then watch(d) end end) end end) end
    end
    local function restoreAll()
        for d in pairs(ST.objConns) do pcall(function() if propOf(d) == "Text" then local u = unfix(d.Text) if u ~= d.Text then d.Text = u end elseif propOf(d) == "Image" and ST.orig[d] then d.Image = ST.orig[d] end end) end
        ST.written, ST.orig = setmetatable({}, { __mode = "k" }), setmetatable({}, { __mode = "k" })
    end
    local function refresh()
        rebuild()
        for _, p in ipairs(Players:GetPlayers()) do setHum(p) end
        restoreAll()
        if active() then if ST.watching then for d in pairs(ST.objConns) do pcall(process, d) end else startWatch() end end
    end
    local function applyCore()
        pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.PlayerList, not ST.HidePlayerList) end)
        if ST.HideChat then pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Chat, false) end) pcall(function() TextChatService.ChatWindowConfiguration.Enabled = false end)
        else pcall(function() StarterGui:SetCoreGuiEnabled(Enum.CoreGuiType.Chat, true) end) pcall(function() TextChatService.ChatWindowConfiguration.Enabled = true end) end
    end
    track(Players.PlayerAdded:Connect(function() if active() then refresh() end end))
    local B = Tab:AddLeftGroupbox(L["Hide Identity"], "user")
    B:AddToggle("st_me", { Text = L["Hide My Name"], Default = false, Callback = function(v) ST.HideMe = v refresh() end })
    B:AddInput("st_name", { Text = L["Fake Name"], Default = "Player", Finished = true, Callback = function(v) v = tostring(v or ""):gsub("^%s+", ""):gsub("%s+$", "") ST.FakeName = (v ~= "" and v:sub(1, 20)) or "Player" refresh() end })
    B:AddToggle("st_others", { Text = L["Hide Other Names"], Default = false, Callback = function(v) ST.HideOthers = v refresh() end })
    B:AddToggle("st_av", { Text = L["Hide Avatars"], Default = false, Callback = function(v) ST.HideAvatars = v refresh() end })
    local B2 = Tab:AddRightGroupbox(L["Hide Roblox UI"], "monitor")
    B2:AddToggle("st_list", { Text = L["Hide Player List"], Default = false, Callback = function(v) ST.HidePlayerList = v applyCore() end })
    B2:AddToggle("st_chat", { Text = L["Hide Chat"], Default = false, Callback = function(v) ST.HideChat = v applyCore() end })
    onClean(function() ST.HideMe, ST.HideOthers, ST.HideAvatars, ST.HidePlayerList, ST.HideChat = false, false, false, false, false pcall(refresh) pcall(applyCore) for _, c in pairs(ST.conns) do pcall(function() c:Disconnect() end) end end)
end)
